const newMessage = $('Normalize Inquiry Data').item.json;
const existing = $input.all();
let history = [];
let leadRecord = {};

if (existing.length > 0 && existing[0].json && existing[0].json.session_id) {
  leadRecord = existing[0].json;
  try {
    history = leadRecord.conversation_history ? JSON.parse(leadRecord.conversation_history) : [];
  } catch (e) {
    history = [];
  }
}

history.push({ role: 'user', content: newMessage.message_text, timestamp: newMessage.timestamp });

if (history.length > 20) {
  history = history.slice(history.length - 20);
}

return [{
  json: {
    ...newMessage,
    is_existing_lead: !!leadRecord.session_id,
    lead_id: leadRecord.lead_id || newMessage.session_id,
    conversation_history: JSON.stringify(history),
    previous_lead_score: Number(leadRecord.lead_score) || 0,
    previous_service: leadRecord.service || newMessage.selected_service || '',
    follow_up_count: Number(leadRecord.follow_up_count) || 0,
    opted_out: leadRecord.opted_out === true || leadRecord.opted_out === 'true'
  }
}];

