// Build a short availability note for the next 5 business days.
// For production, diff busy events against specialist working hours per service.
const events = $input.all().map(i => i.json);
const baseReply = $('Save Lead Record').item.json.output.reply_text;

let suggestion = 'Your requirements have been captured. An Al Marzaan specialist can now review your information and reach out to confirm consultation timing.';
if (events.length === 0) {
  suggestion = 'Your requirements have been captured. Our team has good availability this week - a specialist will confirm a consultation time shortly.';
}

return [{
  json: {
    final_reply_text: `${baseReply}\n\n${suggestion}`
  }
}];

// Determine which leads are due for a follow-up today:
// Follow-up 1: 1 day after last contact
// Follow-up 2: 3 days after last contact
// Follow-up 3: 7 days after last contact
// Max 3 automated follow-ups. Respects opt-outs and leads already flagged for a human/consultation.

const now = new Date();
const MS_DAY = 24 * 60 * 60 * 1000;
const results = [];

for (const item of $input.all()) {
  const lead = item.json;

  const optedOut = lead.opted_out === true || lead.opted_out === 'true';
  const requiresHuman = lead.requires_human === true || lead.requires_human === 'true';
  const consultationRequested = lead.consultation_requested === true || lead.consultation_requested === 'true';
  const followUpCount = Number(lead.follow_up_count) || 0;
  const lastContact = lead.last_contact_date ? new Date(lead.last_contact_date) : null;

  // Don't auto-follow-up leads already routed to a human or who booked a consultation
  if (optedOut || requiresHuman || consultationRequested || !lastContact || followUpCount >= 3) {
    continue;
  }

  const daysSince = (now - lastContact) / MS_DAY;
  const scheduleDays = [1, 3, 7];
  const nextStep = followUpCount;
  const dueThreshold = scheduleDays[nextStep];

  if (dueThreshold !== undefined && daysSince >= dueThreshold) {
    const name = lead.visitor_name || 'there';
    const service = lead.service || 'your enquiry';
    let message;

    if (nextStep === 0) {
      message = `Hi ${name}, following up on your enquiry about ${service} with Al Marzaan Global Consulting. Happy to answer any further questions or arrange a consultation whenever suits you.`;
    } else if (nextStep === 1) {
      message = `Hi ${name}, checking in once more regarding ${service}. If your requirements have changed or you'd like updated guidance, just let us know - no pressure at all.`;
    } else {
      message = `Hi ${name}, this will be our last check-in for now regarding ${service}. If you'd like to pick things back up in the future, Al Marzaan is always here to help. Wishing you the best with your business.`;
    }

    results.push({
      json: {
        ...lead,
        follow_up_message: message,
        follow_up_stage_sent: nextStep + 1,
        is_final_followup: nextStep === 2
      }
    });
  }
}

return results;
